using Microsoft.EntityFrameworkCore;

public sealed class OrderPaidHandler(LoyaltyDb db)
{
    public async Task HandleAsync(OrderPaid msg, CancellationToken ct)
    {
        var id = msg.MessageId; // set by the producer, the same on every copy
        if (await db.ProcessedMessages.AnyAsync(p => p.Id == id, ct))
            return; // already applied: just acknowledge it

        var account = await db.Accounts.SingleAsync(
            a => a.CustomerId == msg.CustomerId, ct);
        account.Points += msg.Points;
        db.ProcessedMessages.Add(new ProcessedMessage(id, DateTime.UtcNow));

        // One SaveChanges is one transaction: points and id commit together.
        // A concurrent copy fails on the primary key and rolls back its points
        await db.SaveChangesAsync(ct);
    }
}
